// expected arrival, or without one sent before the moment given, oldest
// first (the dashboard's transferOverdue, I62).
func (q *Queries) OverdueTransfers(ctx context.Context, arg OverdueTransfersParams) ([]OverdueTransfersRow, error) {
	rows, err := q.db.Query(ctx, overdueTransfers, arg.Today, arg.SentBefore)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []OverdueTransfersRow
	for rows.Next() {
		var i OverdueTransfersRow
		if err := rows.Scan(
			&i.ID,
			&i.Number,
			&i.FromSiteID,
			&i.ToSiteID,
			&i.ExpectedArrival,
			&i.SentAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const sendTransferLines = `-- name: SendTransferLines :exec
UPDATE inventory.transfer_lines l
SET sku = u.sku, product_name = u.product_name, unit = u.unit, quantity = u.quantity, entered = nullif(u.entered, '')::jsonb,
    from_location_id = u.from_location_id, sent = u.quantity
FROM (SELECT unnest($2::bigint[]) AS id, unnest($3::text[]) AS sku, unnest($4::text[]) AS product_name,
             unnest($5::text[]) AS unit, unnest($6::numeric[]) AS quantity, unnest($7::text[]) AS entered,
             unnest($8::bigint[]) AS from_location_id) AS u
WHERE l.id = u.id AND l.transfer_id = $1
`

type SendTransferLinesParams struct {
	TransferID      int64
	Ids             []int64
	Skus            []string
	ProductNames    []string
	Units           []string
	Quantities      []pgtype.Numeric
	Entereds        []string
	FromLocationIds []int64
}

// SendTransferLines is a send's lines (I39): resolved to units, snapshotted
// again, with their source location, and sent in full.
func (q *Queries) SendTransferLines(ctx context.Context, arg SendTransferLinesParams) error {
	_, err := q.db.Exec(ctx, sendTransferLines,
		arg.TransferID,
		arg.Ids,
		arg.Skus,
		arg.ProductNames,
		arg.Units,
		arg.Quantities,
		arg.Entereds,
		arg.FromLocationIds,
	)
	return err
}

const setTransferStatus = `-- name: SetTransferStatus :exec
UPDATE inventory.transfers
SET status = $1, revision = revision + 1, updated_at = $2::timestamptz
WHERE id = $3
`

type SetTransferStatusParams struct {
	Status string
	Now    time.Time
	ID     int64
}

// SetTransferStatus is a receive's or a cancel's status (I40, I44).
func (q *Queries) SetTransferStatus(ctx context.Context, arg SetTransferStatusParams) error {
	_, err := q.db.Exec(ctx, setTransferStatus, arg.Status, arg.Now, arg.ID)
	return err
}

const shareTransferSites = `-- name: ShareTransferSites :many
SELECT id, code, name, kind, address_line1, address_line2, postal_code, city, country, status, revision, created_at, updated_at, fulfils_orders FROM inventory.sites WHERE id = ANY($1::bigint[]) ORDER BY id FOR SHARE
`

// ShareTransferSites takes FOR SHARE on a transfer's from and to site in id
// order (I38 step 4), so an archive that committed first is seen and one
// racing the action waits; their status is judged after.
func (q *Queries) ShareTransferSites(ctx context.Context, ids []int64) ([]InventorySite, error) {
	rows, err := q.db.Query(ctx, shareTransferSites, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []InventorySite
	for rows.Next() {
		var i InventorySite
		if err := rows.Scan(
			&i.ID,
			&i.Code,
			&i.Name,
			&i.Kind,
			&i.AddressLine1,
			&i.AddressLine2,
			&i.PostalCode,
			&i.City,
			&i.Country,
			&i.Status,
			&i.Revision,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.FulfilsOrders,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const siteHasOpenTransfers = `-- name: SiteHasOpenTransfers :one
SELECT EXISTS (
    SELECT 1 FROM inventory.transfers
    WHERE (from_site_id = $1::bigint OR to_site_id = $1::bigint) AND status IN ('sent', 'partly_received')
)
`

// SiteHasOpenTransfers reports whether a sent or partly received transfer
// names the site, so archiving it is refused (site_has_open_transfers, I48).
func (q *Queries) SiteHasOpenTransfers(ctx context.Context, siteID int64) (bool, error) {
	row := q.db.QueryRow(ctx, siteHasOpenTransfers, siteID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const siteHasTransfers = `-- name: SiteHasTransfers :one
SELECT EXISTS (
    SELECT 1 FROM inventory.transfers WHERE from_site_id = $1::bigint OR to_site_id = $1::bigint
)
`

// SiteHasTransfers reports whether any transfer names the site, so deleting
// it is refused (site_has_transfers, I48).
func (q *Queries) SiteHasTransfers(ctx context.Context, siteID int64) (bool, error) {
	row := q.db.QueryRow(ctx, siteHasTransfers, siteID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const subtreeInTransit = `-- name: SubtreeInTransit :one
SELECT EXISTS (
    SELECT 1
    FROM inventory.transfer_lines tl
    JOIN inventory.locations l ON l.id = tl.from_location_id
    WHERE tl.sent > tl.received + tl.missing + tl.returned
      AND (l.id = $1::bigint OR l.ancestors @> ARRAY[$1::bigint])
)
`

// SubtreeInTransit reports whether a line still in transit was sent from the
// location or one below it, so archiving it is refused (location_in_transit,
// I48): the cancel's way home.
func (q *Queries) SubtreeInTransit(ctx context.Context, locationID int64) (bool, error) {
	row := q.db.QueryRow(ctx, subtreeInTransit, locationID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

