const updateTransferHeader = `-- name: UpdateTransferHeader :exec
UPDATE inventory.transfers
SET from_site_id = $1, to_site_id = $2, reference = $3, note = $4,
    expected_arrival = $5, revision = revision + 1, updated_at = $6::timestamptz
WHERE id = $7
`

type UpdateTransferHeaderParams struct {
	FromSiteID      int64
	ToSiteID        int64
	Reference       *string
	Note            *string
	ExpectedArrival pgtype.Date
	Now             time.Time
	ID              int64
}

// UpdateTransferHeader replaces a draft's header and moves its revision on
// (I37).
func (q *Queries) UpdateTransferHeader(ctx context.Context, arg UpdateTransferHeaderParams) error {
	_, err := q.db.Exec(ctx, updateTransferHeader,
		arg.FromSiteID,
		arg.ToSiteID,
		arg.Reference,
		arg.Note,
		arg.ExpectedArrival,
		arg.Now,
		arg.ID,
	)
	return err
}

const variantInTransit = `-- name: VariantInTransit :one
SELECT coalesce(sum(sent - received - missing - returned), 0)::text AS quantity, count(DISTINCT transfer_id)::int AS transfers
FROM inventory.transfer_lines
WHERE variant_id = $1 AND sent > received + missing + returned
`

type VariantInTransitRow struct {
	Quantity  string
	Transfers int32
}

// VariantInTransit is what of a variant is in transit on every transfer, and
// on how many transfers, on the caller's transaction (the holder, I47).
func (q *Queries) VariantInTransit(ctx context.Context, variantID int32) (VariantInTransitRow, error) {
	row := q.db.QueryRow(ctx, variantInTransit, variantID)
	var i VariantInTransitRow
	err := row.Scan(&i.Quantity, &i.Transfers)
	return i, err
}
